@startuml

class Airline {
  + Name : string
}

class Airport {
  + Name : string
  + Address : string
  + RunwayCount : int
}

class Aircraft {
  + Name : string
  + Type : string
  + YearOfManufacture : int
  + NextInspection : date
}

class PassengerAircraft extends Aircraft {
  + NumberOfSeats : int
}

class SeatCategory {
  + Designation : string
  + OffersEntertainment : boolean
  + SeatCount : int
}

class Flight {
  + FlightNumber : string
  + Date : date
}

class FlightExecution {
  + Date : date
}

class Passenger {
  + Name : string
  + PassportNumber : string
}

class Ticket {
  + TicketNumber : string
  + Price : float
  + UpgradeDesired : boolean
}

class Employee {
  + Name : string
  + DateOfEmployment : date
}

class FlightAttendant extends Employee {
  + IsChiefStewardess : boolean
}

class Pilot extends Employee {
  + License : string
}

Airline "0..1" -- "0..*" Aircraft
Airline "1" -- "0..*" Employee
Aircraft "0..1" -- "0..1" Airport : home airport
Aircraft "1" -- "0..*" Flight
Flight "1" -- "0..*" FlightExecution
Flight "1" -- "1" Airport : departure airport
Flight "1" -- "1" Airport : destination airport
FlightExecution "1" -- "0..*" FlightAttendant
FlightExecution "1" -- "1 Captain" Pilot
FlightExecution "1" -- "1..2 Co-pilot" Pilot
FlightExecution "0..*" -- "1" Passenger : takes part in
FlightExecution "1" -- "0..*" Ticket
Ticket "0..*" -- "1" Passenger
Ticket "0..*" -- "1" SeatCategory

@enduml

